pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.deposit{value: 1 wei}();
        // REFERENCE: balances[alice] = 1, contract balance = 1
        // BUGGY: underflow => balances[alice] = 2^256-1

        // Try refund: in REFERENCE it succeeds and transfers 1 wei to alice
        // In buggy it will attempt to transfer 2^256-1 wei which reverts (insufficient balance)
        vm.prank(alice);
        bool ok;
        try c.refund() { ok = true; } catch { ok = false; }
        // REFERENCE: ok = true (refund succeeds)
        // BUGGY: ok = false (revert due to underflow/insufficient balance)
        assertTrue(ok);
    }
}

