pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 10 ether
        vm.deal(address(c), 10 ether);
        // Actor Alice deposits 5 ether
        address alice = address(0x1234);
        vm.deal(alice, 5 ether);
        vm.prank(alice);
        c.deposit{value: 5 ether}();
        // First refund: Alice gets back 5 ether, balance becomes 0
        vm.prank(alice);
        c.refund();
        // Second refund: In the reference, balance was set to 0, then transferred 0? Actually after refund, balances[alice] = 0, then transfers old balance (5), then sets balances[alice] = 0. So second refund should transfer 0. But the buggy version sets balances[alice]=tmp__1 after transfer, so balances[alice] is 5 again, so second refund transfers 5.
        // Let's check: reference after first refund: balances[alice]=0. Second refund: tmp__1=0, balances[alice]=0, transfer(0), balances[alice]=0. So Alice gets 0 total from second refund.
        // Buggy after first refund: balances[alice]=5 (because reassigned). Second refund: tmp__1=5, balances[alice]=0, transfer(5), balances[alice]=5. So Alice gets extra 5.
        // But we need observable divergence. Let's use migrateTo to check contract balance.
        // After two refunds, reference contract balance = 10 - 5 - 0 = 5 ether (the 5 ether that was already there from vm.deal stays), actually initial: 10 ether from vm.deal + 5 from alice = 15 ether? Wait: vm.deal(address(c), 10 ether) gives contract 10, then alice deposits 5, so contract has 15. First refund transfers 5 to alice, contract balance 10. Second refund: reference transfers 0, contract balance 10. Buggy: first refund transfers 5, contract balance 10, but then buggy reassigns balance to 5 (state variable), second refund transfers 5, contract balance 5. So contract balance diverges.
        // Create a prank as creator to call migrateTo and check balance
        address creator = address(this); // the test contract is the deployer, but constructor sets creator = msg.sender, which is the test contract (this) because setUp is run by test contract
        vm.prank(creator);
        uint256 bal = address(c).balance;
        assertEq(bal, 10 ether);
    }
}

