pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: give user 1 ether and let them deposit it
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.deposit{value: 1 ether}();

        // User calls refund() — reference transfers, buggy version does not
        // Check contract balance before refund to compute expected after
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(user);
        c.refund();

        // After refund, reference transfers all user's balance (1 ether) to user,
        // so contract balance decreases by 1 ether.
        // In the buggy version, the transfer line is missing, so contract balance stays unchanged.
        uint256 contractBalanceAfter = address(c).balance;
        assertEq(contractBalanceAfter, contractBalanceBefore - 1 ether);
    }
}

