import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(address(this)); // deployer
        c.migrateTo(bob);
        // In reference, migrateTo sends address(this).balance to bob, so c.balance becomes 0.
        // In bug, migrateTo sends 0, so c.balance remains 1 ether.
        assertEq(address(c).balance, 0);
    }
}
